VALUES
  (12, true, '12|||זכויות למתמודדים עם פגיעה נפשית', '12|||מדריך זכויות למתמודדים עם פגיעה נפשית או פוסט טראומה.', '{"org":"אגף השיקום, משרד הבטחון","svc":"מדריך זכויות למתמודדים עם פגיעה נפשית או פוסט טראומה.","target":"נכי צה״ל וכוחות הביטחון, ומי שנמצא בתהליך הכרה","region":"כל הארץ","cost":"משרד הביטחון","specialty":"","approaches":"","languages":"","diseases":"","notes":"נפש אחת, הבית הבטוח והטיפולים במימון בכרטיסים נפרדים.","meeting":"","web":"https://shikum.mod.gov.il/rights/injury-type/mental","add":"https://shikum.mod.gov.il/medical/treatment/therapy#3","addLabel":"טיפולים רגשיים במימון","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Rehabilitation Department, Ministry of Defense","svc":"A rights guide for people coping with a mental injury or post-traumatic stress.","target":"Disabled veterans of the IDF and the security forces, and a person in the recognition process","region":"Nationwide","cost":"The Ministry of Defense","notes":"Nefesh Ahat, the safe house, and the funded treatments are on separate cards.","addLabel":"Funded emotional treatments","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://shikum.mod.gov.il/rights/injury-type/mental. קו 8944 לא עלה לכרטיס. הניסוח אושר עם אצוות הפורטלים.'),
  (16, true, '16|||שירותים למתמודד
אינדקס מטפלים
פורומים
ועוד ועוד', '16|||מידע על שירותי בריאות הנפש, ואינדקס מטפלים.', '{"org":"פורטל בריאות הנפש בישראל","svc":"מידע על שירותי בריאות הנפש, ואינדקס מטפלים.","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"","meeting":"","web":"https://www.mh-israel.co.il/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"The Mental Health Portal in Israel","svc":"Information on mental-health services, and an index of therapists.","region":"Nationwide","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: עמוד הבית החזיר שגיאה. עמודי הפנים מתארים מידע, אינדקס מטפלים, בתי חולים וזכויות. אין טלפון של הפורטל עצמו. הניסוח אושר עם אצוות הפורטלים.'),
  (17, true, '17|||', '17|||הנגשת מידע למתמודדים ולבני משפחה, על הגופים שיכולים לסייע. בעלון.', '{"org":"החלמה","svc":"הנגשת מידע למתמודדים ולבני משפחה, על הגופים שיכולים לסייע. בעלון.","target":"","region":"כל הארץ","founded":"2025","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"פנייה ליוסי שמעונוביץ. המשרד במשעול עוזרד 20, ירושלים.","meeting":"","web":"","phone":"054-4749809","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Hachlama","svc":"Information for people coping with a mental illness and for family members, about the bodies that can help. In a leaflet.","region":"Nationwide","founded":"2025","notes":"Ask for Yossi Shimonovitz. The office is at 20 Mishol Ozerad, Jerusalem.","phone":"054-4749809","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: אין אתר. ברשם העמותות, עמותה 580810695, נרשמה ב-3.2.2025, והמטרה היא עלונים. הטלפון נשאר, והשם ירד מהכפתור. הניסוח אושר עם אצוות הפורטלים.'),
  (18, true, '18|||Provides English-speakers with access to verified mental health specialists as well as resources and information on navigating the mental health system in Israel', '18|||אינדקס מטפלים דוברי אנגלית בישראל, ומידע על מערכת בריאות הנפש.', '{"org":"GET HELP Israel","svc":"אינדקס מטפלים דוברי אנגלית בישראל, ומידע על מערכת בריאות הנפש.","target":"","region":"כל הארץ","cost":"החיפוש באתר ללא עלות","specialty":"","approaches":"","languages":"אנגלית","diseases":"","notes":"","meeting":"","web":"https://gethelpisrael.com/","phone":"072-3971307","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"GET HELP Israel","svc":"An index of English-speaking therapists in Israel, and information on the mental-health system.","region":"Nationwide","cost":"Search on the site is at no cost","languages":"English","phone":"072-3971307","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://gethelpisrael.com/ ועמוד יצירת הקשר. 072-3971307 הוא שירות לפונים. קו אנשי המקצוע, השעות, והמשפט שזה אינו חירום לא עלו. הניסוח אושר עם אצוות הפורטלים.'),
  (19, true, '19|||אינדקס שירותים למענה נפשי וטיפול בפוסט-טראומה', '19|||רשימת מענים נפשיים לחיילי סדיר, למילואים ולמשוחררים, וגם למשפחות.', '{"org":"בטיפולנט","svc":"רשימת מענים נפשיים לחיילי סדיר, למילואים ולמשוחררים, וגם למשפחות.","target":"חיילי סדיר, מילואים ומשוחררים, ובני משפחה","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"ההמלצה בעמוד היא לפנות קודם למענים של הצבא. הקווים עצמם בכרטיסים נפרדים.","meeting":"","web":"https://www.betipulnet.co.il/articles/%D7%97%D7%A8%D7%93%D7%94_%D7%95%D7%A4%D7%95%D7%A1%D7%98_%D7%98%D7%A8%D7%90%D7%95%D7%9E%D7%94_%D7%A2%D7%9C_%D7%A8%D7%A7%D7%A2_%D7%9C%D7%90%D7%95%D7%9E%D7%99/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Betipulnet","svc":"A list of mental-health services for regular soldiers, for reservists, and for veterans, and also for families.","target":"Regular soldiers, reservists, veterans, and family members","region":"Nationwide","notes":"The page recommends turning first to the army services. The lines themselves are on separate cards.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול עמוד בטיפולנט מ-25.07.2026 לחיילי סדיר, מילואים ומשוחררים. מספרי הקווים לא הועתקו. הניסוח אושר עם אצוות הפורטלים.'),
  (21, false, '21|||רשת לאומית לחוסן נפשי המאפשרת יצירת כלים אינטראקטיביים מותאמים לקהלי יעד שונים', '21|||כלים לתרגול חוסן נפשי, מותאמים לקהלים שונים. באתר.', '{"org":"רי״ל","svc":"כלים לתרגול חוסן נפשי, מותאמים לקהלים שונים. באתר.","target":"","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"פרויקט של VIVID ושל הקואליציה הישראלית לטראומה. נט״ל בכרטיס נפרד.","meeting":"","web":"https://www.ril.org.il/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"RIL","svc":"Resilience-practice tools, fitted to different audiences. On the site.","region":"Nationwide","cost":"At no cost","notes":"A project of VIVID and of the Israel Trauma Coalition. Natal is on a separate card.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://www.ril.org.il/. הכלים שאושרו מוצעים חינם. hello@VIVID.me הוא לפנייה של גופים שמוסיפים כלים, ולא עלה. נט״ל באותה שורה לא נגע. הניסוח אושר עם אצוות הפורטלים.'),
  (23, true, '23|||אינדקס שירותים', '23|||מאגר ארגוני סיוע וקווי חירום.', '{"org":"סה״ר","svc":"מאגר ארגוני סיוע וקווי חירום.","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"סה״ר אינה אחראית למידע של כל גוף. קו סה״ר בכרטיס נפרד.","meeting":"","web":"https://sahar.org.il/%d7%9e%d7%90%d7%92%d7%a8-%d7%90%d7%a8%d7%92%d7%95%d7%a0%d7%99-%d7%a1%d7%99%d7%95%d7%a2/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Sahar","svc":"An index of help organizations and emergency lines.","region":"Nationwide","notes":"Sahar is not responsible for the information of each body. The Sahar line is on a separate card.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול מאגר ארגוני הסיוע באתר סה״ר. שעות הצאט לא עלו. קו סה״ר בכרטיס נפרד. הניסוח אושר עם אצוות הפורטלים.'),
  (27, true, '27|||אינדקס שירותים למתמודדי נפש', '27|||אינדקס שירותי דיור, תעסוקה, פנאי וליווי למתמודדים ולבני משפחה.', '{"org":"רגיש לי","svc":"אינדקס שירותי דיור, תעסוקה, פנאי וליווי למתמודדים ולבני משפחה.","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"","meeting":"","web":"https://www.ragish.li/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ragish Li","svc":"An index of housing, employment, leisure, and accompaniment services for people coping with mental illness and for family members.","region":"Nationwide","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://www.ragish.li/. דיור, תעסוקה, פנאי, משפחות, השכלה וליווי. אין טלפון של האתר. הניסוח אושר עם אצוות הפורטלים.'),
  (59, true, '59|||מיצוי זכויות', '59|||תוכנית רדיו על מיצוי זכויות סוציאליות. בכאן, רשת ב׳.', '{"org":"זה מגיע לכם","svc":"תוכנית רדיו על מיצוי זכויות סוציאליות. בכאן, רשת ב׳.","target":"","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"אפשר לכתוב לתוכנית.","meeting":"","web":"https://www.kan.org.il/content/kan/kan-b/p-10067/","add":"https://www.facebook.com/drgilitamir/","addLabel":"פייסבוק","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"ze@kan.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Ze Magia Lachem","svc":"A radio program on realizing social rights. On Kan, Reshet Bet.","region":"Nationwide","cost":"At no cost","notes":"You can write to the program.","addLabel":"Facebook","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"ze@kan.org.il","emailLabel":"Email"}'::jsonb, '28.11.2026: נבדק מול עמוד כאן של זה מגיע לכם. ze@kan.org.il. שעות השידור לא עלו. הפייסבוק נשאר. הניסוח אושר עם אצוות הפורטלים.'),
  (202, true, '202|||מידע, הכשרות, מוקדי חוסן ושותפות ארצית בטראומה וחוסן (Israel Trauma Coalition)', '202|||ארגון גג למרכזי חוסן ולהכשרה בחירום ובטראומה.', '{"org":"הקואליציה הישראלית לטראומה","svc":"ארגון גג למרכזי חוסן ולהכשרה בחירום ובטראומה.","target":"","region":"כל הארץ","founded":"2001","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"המשרד בנווה אילן. ער״ן, נט״ל, מוקד החוסן והדסה בכרטיסים נפרדים.","meeting":"","web":"https://israeltraumacoalition.org/","phone":"02-6722618","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@itc-office.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"The Israel Trauma Coalition","svc":"An umbrella body for resilience centers and for training in emergency and trauma.","region":"Nationwide","founded":"2001","notes":"The office is in Neve Ilan. Eran, Natal, the resilience line, and Hadassah are on separate cards.","phone":"02-6722618","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@itc-office.org.il","emailLabel":"Email"}'::jsonb, '28.11.2026: נבדק מול https://israeltraumacoalition.org/. נוסדה ב-2001. הטלפון של המשרד 02-6722618. *5486 והדסה הם קווים של גופים אחרים, וירדו. הניסוח אושר עם אצוות הפורטלים.'),
  (244, true, '244|||מידע, זכויות ואיתור ספקי שירות בסל שיקום', '244|||מידע על סל שיקום, ואיתור ספקי שירות. באתר.', '{"org":"סל שיקום","svc":"מידע על סל שיקום, ואיתור ספקי שירות. באתר.","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"התוכן באתר נכתב על ידי משתמשים. המשרד בירמיהו 39, ירושלים.","meeting":"","web":"https://salshikum.org/","phone":"*5400","phoneLabel":"משרד הבריאות","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"salshikum@outlook.com","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Rehabilitation Basket","svc":"Information on the rehabilitation basket, and a way to find service providers. On the site.","region":"Nationwide","notes":"The content on the site is written by users. The office is at 39 Yirmiyahu, Jerusalem.","phone":"*5400","phoneLabel":"Ministry of Health","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"salshikum@outlook.com","emailLabel":"Email"}'::jsonb, '28.11.2026: נבדק מול https://salshikum.org/. *5400 רשום שם כמוקד משרד הבריאות. salshikum@outlook.com. ירמיהו 39, ירושלים. הניסוח אושר עם אצוות הפורטלים.'),
  (255, true, '255|||מפה ומאגר מענים טיפוליים ונפשיים בישראל לילדים, נוער ומבוגרים', '255|||מפה של מענים טיפוליים ונפשיים לילדים, לנוער ולמבוגרים.', '{"org":"מפה לנפש","svc":"מפה של מענים טיפוליים ונפשיים לילדים, לנוער ולמבוגרים.","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"מרפאות, אשפוז, חינוך מיוחד, רווחה, מסגרות חוץ-ביתיות, עמותות וקווי סיוע. פרויקט קהילתי.","meeting":"","web":"https://mapalanefesh.org.il/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Mapa LaNefesh","svc":"A map of treatment and mental-health services for children, for youth, and for adults.","region":"Nationwide","notes":"Clinics, hospitalization, special education, welfare, out-of-home settings, associations, and help lines. A community project.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://mapalanefesh.org.il/. העמוד הוא מפה. המשפט שזה אינו ייעוץ רפואי לא עלה. הניסוח אושר עם אצוות הפורטלים.'),
