h-il.org/emergency?entry=103&section=anxiety_apps), [the combat-reaction unit](https://nefesh-il.org/rights?entry=214&section=mod), and [funded emotional treatments](https://nefesh-il.org/rights?entry=218&section=mod) are on separate cards.","webLabel2":"Service guide","addLabel":"Find a therapist","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '28.11.2026: נבדק מול https://shikum.mod.gov.il/medical/mental-therapy. התיאור נשאר. המשפט שזה אינו קו סיוע ירד. הקישורים לכרטיסים נשארו. הניסוח אושר עם אצוות הפורטלים.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM portal_wording w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN portal_wording w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM portal_wording w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN portal_wording w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

COMMIT;
